// 解析 Agent 输出的 JSON，拆分成多行供 Postgres 插入
const output = $input.first().json.output;

let result;
try {
  // 去掉可能的 markdown 代码块包裹
  const clean = output.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  result = JSON.parse(clean);
} catch(e) {
  // 如果解析失败，存储原始文本
  return [{
    json: {
      tenant_id: 'demo',
      page_url: 'ALL',
      facts: JSON.stringify({}),
      diagnosis: output,
      strategy: '',
      agent_trace: JSON.stringify({ error: 'JSON parse failed', raw: output.slice(0, 500) })
    }
  }];
}

const rows = (result.page_diagnoses || []).map(d => ({
  json: {
    tenant_id: 'demo',
    page_url: d.page_url,
    facts: JSON.stringify(d.facts || {}),
    diagnosis: d.diagnosis || '',
    strategy: (d.strategy || '') + (d.expected_effect ? ' | 预期效果：' + d.expected_effect : ''),
    agent_trace: JSON.stringify({
      summary: result.summary,
      visitor_profile: result.visitor_profile || null
    })
  }
}));

// 如果没有 page_diagnoses，保存 summary
if (rows.length === 0) {
  rows.push({
    json: {
      tenant_id: 'demo',
      page_url: 'ALL',
      facts: JSON.stringify({}),
      diagnosis: result.summary || output,
      strategy: '',
      agent_trace: JSON.stringify(result)
    }
  });
}

return rows;
